 run("watchdog-does-not-charge-replacement",[&](const auto& root){Queue q(root);q.enqueue(Json::array({shortcut()}));const auto token=q.start();const auto old=q.claim(token);const auto key=stringField(old,"key");q.enqueue(Json::array({shortcut("8")}));q.recover(token,"worker-stalled",key);const auto after=q.document()["jobs"][key];check(after.value("attempts",99)==0&&after.value("retryAt",int64_t{-1})==0&&after.value("steamAccount",std::string{})=="8","old watchdog cannot charge new shortcut owner");});
 run("late-promotion-does-not-delete-replacement",[&](const auto& root){Queue q(root);q.enqueue(Json::array({shortcut()}));const auto token=q.start();const auto old=q.claim(token);const auto key=stringField(old,"key");q.enqueue(Json::array({shortcut("8")}));cache(q);const auto before=q.document();const bool promoted=q.promoteIdentity(token,old);const auto after=q.document();atomicWrite(root/L"late-promotion.json",{{"promoted",promoted},{"before",before},{"after",after}});check(!promoted&&after["jobs"].contains(key)&&after["jobs"][key]["steamAccount"]=="8","old identity promotion cannot delete replacement file job");check(!after["jobs"].contains("steam-570")&&!fs::exists(root/L"config"/L"game-media.json"),"rejected promotion creates no canonical job or media record");q.result(token,key,false,"media-identity-unconfirmed");const auto next=q.claim(token);check(next.value("steamAccount",std::string{})=="8","new owner can claim after stale identity retires");check(q.promoteIdentity(token,next),"current replacement owner can reuse verified identity");q.end(token,"paused");});
