 run("old-epoch-or-revision-cannot-resume",[&](const fs::path& root){Store store(root);auto old=ticket(413);proof["revision"]=uint64_t{2};check(store.resolve(old).value("status",std::string{})=="consumer-inactive","old revision cannot query");proof["ownerEpoch"]="owner-B";check(!store.begin(old).value("acquired",false),"old epoch cannot acquire on regain");auto fresh=old;fresh["demandEpoch"]="owner-B";fresh["demandRevision"]=uint64_t{2};check(store.begin(fresh).value("acquired",false),"new valid epoch resumes once");});
 run("old-steam-callback-cannot-charge-ymcc-owner",[&](const fs::path& root){Store store(root);const auto old=store.begin(ticket(414));check(old.value("acquired",false),"Steam lease created");proof["foreground"]=false;proof["ownerEpoch"]="owner-B";auto independent=target(414);independent["demandConsumer"]="ymcc";const auto next=store.begin(independent);check(next.value("acquired",false)&&next["taskId"]!=old["taskId"],"independent YMCC consumer takes revoked same-process lease");measuredWrites=0;measureWrites=true;store.fail(old);store.finish(old);measureWrites=false;check(measuredWrites==0,"late Steam failure/completion writes nothing");const auto current=store.resolve(independent);check(current["taskId"]==next["taskId"]&&current.value("attempts",0)==0&&current.value("retryAt",int64_t{0})==0,"late Steam result cannot spend new owner's budget");});
 run("blurred-playback-error-cannot-quarantine-good-asset",[&](const fs::path& root){Store store(root);auto lease=store.begin(ticket(415));auto published=store.publish(lease,video(root),false);store.finish(published);auto failure=published;failure["action"]="playback-failed";failure["slot"]="dynamic";failure["assetId"]=published["asset"]["id"];proof["foreground"]=false;measuredWrites=0;measureWrites=true;store.edit(failure);measureWrites=false;check(measuredWrites==0,"revoked player cannot persist playback failure");const auto current=store.resolve(target(415));check(current.value("dynamicReady",false)&&current.value("invalidSlots",Json::object()).empty(),"good shared video remains playable by independent consumers");});
